    "title": "Event title",
    "startDateTime": "YYYY-MM-DDTHH:MM:SS",
    "endDateTime": "YYYY-MM-DDTHH:MM:SS",
    "location": {
      "name": "Location name",
      "address": "Full address",
      "isVirtual": false
    },
    "description": "Detailed description of the event",
    "attendees": [
      {
        "name": "Attendee name",
        "email": "attendee@example.com",
        "required": true
      }
    ],
    "reminders": [
      {
        "type": "notification",
        "minutesBefore": 15
      }
    ]
  }
}
```

