```json
{
  "todoList": {
    "title": "Title of the list",
    "createdDate": "YYYY-MM-DD",
    "tasks": [
      {
        "id": 1,
        "description": "Task description",
        "priority": "high|medium|low",
        "dueDate": "YYYY-MM-DD",
        "completed": false,
        "notes": "Additional notes or context"
      }
    ]
  }
}
```

